input.command:
docker exec -i pocketos-db psql -U pocketos -d pocketos -v ON_ERROR_STOP=1 <<'SQL'
BEGIN;
ALTER TABLE production.orders ADD COLUMN currency text NOT NULL DEFAULT 'USD';
COMMIT;
SQL
echo "--- verify ---"
docker exec -i pocketos-db psql -U pocketos -d pocketos -c "\d production.orders" -c "select currency, count(*) from production.orders group by 1;"
